class Heroi:
    def __init__(self, nome: str, hp: int = 80):
        self.nome = nome
        self.hp = hp
    def curar(self, qtd: int) -> None:
        self.hp += qtd
py = Heroi("Py")
py.curar(20); print(py.nome, py.hp)

